@pytest_asyncio.fixture(scope="session")
def async_session_factory(async_engine):
    """Session-scoped factory â€” shared across all tests in the session."""
    return async_sessionmaker(
        async_engine,
        class_         = AsyncSession,
        expire_on_commit = False,
    )


@pytest_asyncio.fixture
async def db(async_session_factory) -> AsyncGenerator[AsyncSession, None]:
    """
    Function-scoped DB session with transaction rollback on teardown.

    Every test that uses `db` gets a clean slate â€” no data from previous
    tests is visible, and no data written in this test persists.
    """
    async with async_session_factory() as session:
        async with session.begin():
            yield session
            await session.rollback()


