def make_developer_response(
    files: dict[str, str] | None = None,
) -> MagicMock:
    """
    Build a mock developer LLM response with well-formed <file> blocks.

    Parameters
    ----------
    files
        {relative_path: file_content} â€” defaults to a single placeholder file.
    """
    if files is None:
        files = {
            "src/agents/planner.py": (
                "# Code Generated by Sidekick is for learning and experimentation purposes only.\n"
                '"""Planner agent."""\n'
                "from __future__ import annotations\n\n"
                "def plan(task: str) -> list[str]:\n"
                '    """Break task into steps."""\n'
                "    return [task]\n"
            )
        }

    blocks = "\n".join(
        f'<file path="{path}">\n{content}\n</file>'
        for path, content in files.items()
    )
    return _make_chat_response(f"Here are the generated files:\n\n{blocks}")


def make_reviewer_pass_response(reviewer: str = "workflow_reviewer") -> MagicMock:
    """Build a passing reviewer JSON response."""
    return _make_chat_response(
        '{"passed": true, "feedback": "", "severity": "blocking"}'
    )


def make_reviewer_fail_response(
    reviewer: str  = "workflow_reviewer",
    feedback: str  = "Missing orchestrator dispatch logic.",
    severity: str  = "blocking",
) -> MagicMock:
    """Build a failing reviewer JSON response."""
    return _make_chat_response(
        f'{{"passed": false, "feedback": "{feedback}", "severity": "{severity}"}}'
    )


def make_critic_pass_response() -> MagicMock:
    """Build a passing critic JSON response."""
    return _make_chat_response(
        '{"passed": true, "issues": [], "feedback": ""}'
    )


def make_critic_fail_response(feedback: str = "Loop is unbounded.") -> MagicMock:
    """Build a failing critic JSON response."""
    return _make_chat_response(
        f'{{"passed": false, "issues": ["{feedback}"], "feedback": "{feedback}"}}'
    )


